<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
/** Éditeur visuel ; les valeurs restent dans le moteur de réglages existant. */
class Nodevora_Design_Admin {
	public static function labels() { return array('primary_color'=>__('Primary color','nodevora-customer-rewards-for-woocommerce'),'accent_color'=>__('Accent color','nodevora-customer-rewards-for-woocommerce'),'button_background'=>__('Button background','nodevora-customer-rewards-for-woocommerce'),'button_text'=>__('Button text','nodevora-customer-rewards-for-woocommerce'),'button_hover_background'=>__('Button hover background','nodevora-customer-rewards-for-woocommerce'),'button_hover_text'=>__('Button hover text','nodevora-customer-rewards-for-woocommerce'),'card_background'=>__('Card background','nodevora-customer-rewards-for-woocommerce'),'card_border'=>__('Card border','nodevora-customer-rewards-for-woocommerce'),'text_color'=>__('Text color','nodevora-customer-rewards-for-woocommerce'),'info_background'=>__('Information background','nodevora-customer-rewards-for-woocommerce'),'info_text'=>__('Information text','nodevora-customer-rewards-for-woocommerce')); }
	public static function groups() { return array('cart'=>__('Cart','nodevora-customer-rewards-for-woocommerce'),'checkout'=>__('Checkout','nodevora-customer-rewards-for-woocommerce'),'account'=>__('My Account','nodevora-customer-rewards-for-woocommerce'),'history'=>__('History','nodevora-customer-rewards-for-woocommerce'),'notice'=>__('Notices','nodevora-customer-rewards-for-woocommerce')); }
	private static function field($key,$label,$settings,$advanced=false) {
		$required=in_array($key,array('primary_color','accent_color'),true);$disabled=$advanced&&!Nodevora_Access::advanced()?' disabled':'';
		echo '<div class="nodevora-field'.($advanced?' nodevora-advanced':'').'"><label for="nodevora-color-'.esc_attr($key).'">'.esc_html($label).'</label><input type="text" class="nodevora-color-picker" data-color-for="'.esc_attr($key).'"'.$disabled.' aria-label="'.esc_attr($label).'" value="'.esc_attr(sanitize_hex_color($settings[$key]??'')?:'#0b1638').'"><input id="nodevora-color-'.esc_attr($key).'" class="nodevora-hex" type="text" data-design-key="'.esc_attr($key).'" name="rewardly_loyalty_settings['.esc_attr($key).']" value="'.esc_attr($settings[$key]??'').'"'.$disabled.' pattern="#[a-fA-F0-9]{3}([a-fA-F0-9]{3})?" placeholder="#0b1638"'.($required?' required':'').'><button type="button" class="button-link nodevora-color-reset" data-reset-color="'.esc_attr($key).'">'.esc_html($required?__('Reset to preset','nodevora-customer-rewards-for-woocommerce'):__('Use inherited color','nodevora-customer-rewards-for-woocommerce')).'</button></div>';
	}
	private static function select($key,$label,$options,$s,$advanced=false){echo'<div class="nodevora-field'.($advanced?' nodevora-advanced':'').'"><label for="nodevora-design-'.esc_attr($key).'">'.esc_html($label).'</label><select id="nodevora-design-'.esc_attr($key).'" data-design-key="'.esc_attr($key).'" name="rewardly_loyalty_settings['.esc_attr($key).']"'.($advanced&&!Nodevora_Access::advanced()?' disabled':'').'>';foreach($options as$value=>$text){echo'<option value="'.esc_attr($value).'" '.selected($s[$key]??'',$value,false).'>'.esc_html($text).'</option>';}echo'</select></div>';}
	public static function render() {
		$s=Rewardly_Loyalty_Helpers::get_settings();$labels=self::labels();
		echo'<form method="post" action="options.php" class="rewardly-admin-card" id="nodevora-design">';settings_fields('rewardly_loyalty_group');echo'<input type="hidden" name="rewardly_loyalty_settings[_section]" value="design"><input type="hidden" name="rewardly_loyalty_settings[_reset_design]" value=""><h2>'.esc_html__('Make Nodevora your own','nodevora-customer-rewards-for-woocommerce').'</h2><p>'.esc_html__('Choose a preset, then personalize its colors. The preview uses example data and updates without saving. Changes apply only to Nodevora components.','nodevora-customer-rewards-for-woocommerce').'</p><fieldset class="nodevora-presets"><legend>'.esc_html__('Visual preset','nodevora-customer-rewards-for-woocommerce').'</legend>';
		$presets=Rewardly_Loyalty_Design::presets();
		foreach(array('default'=>__('Nodevora','nodevora-customer-rewards-for-woocommerce'),'minimal'=>__('Minimal','nodevora-customer-rewards-for-woocommerce'),'soft'=>__('Soft','nodevora-customer-rewards-for-woocommerce'))as$value=>$label){echo'<label class="nodevora-preset"><input type="radio" data-design-key="design_template" name="rewardly_loyalty_settings[design_template]" value="'.esc_attr($value).'" '.checked($s['design_template'],$value,false).'><span class="nodevora-swatch" aria-hidden="true" style="background:'.esc_attr($presets[$value]['primary_color']).'"></span><span class="nodevora-swatch" aria-hidden="true" style="background:'.esc_attr($presets[$value]['accent_color']).'"></span>'.esc_html($label).'</label>';}
		echo'</fieldset><div class="nodevora-design-grid"><div><div class="nodevora-fields">';
		foreach($labels as$key=>$label){self::field($key,$label,$s,!in_array($key,array('primary_color','accent_color','button_background','button_text'),true));}
		echo'<div class="nodevora-field"><label for="nodevora-design-radius">'.esc_html__('Corner radius','nodevora-customer-rewards-for-woocommerce').'</label><input type="range" id="nodevora-design-radius" data-design-key="border_radius" name="rewardly_loyalty_settings[border_radius]" min="0" max="30" value="'.esc_attr($s['border_radius']).'"><output id="nodevora-radius-value">'.esc_html($s['border_radius']).'px</output></div>';
		self::select('button_style',__('Button shape','nodevora-customer-rewards-for-woocommerce'),array('rounded'=>__('Rounded','nodevora-customer-rewards-for-woocommerce'),'solid'=>__('Solid','nodevora-customer-rewards-for-woocommerce'),'outline'=>__('Outline','nodevora-customer-rewards-for-woocommerce')),$s);
		self::select('density',__('Spacing','nodevora-customer-rewards-for-woocommerce'),array('comfortable'=>__('Comfortable','nodevora-customer-rewards-for-woocommerce'),'compact'=>__('Compact','nodevora-customer-rewards-for-woocommerce')),$s);
		self::select('card_style',__('Card style','nodevora-customer-rewards-for-woocommerce'),array('soft'=>__('Soft','nodevora-customer-rewards-for-woocommerce'),'outline'=>__('Outline','nodevora-customer-rewards-for-woocommerce'),'filled'=>__('Filled','nodevora-customer-rewards-for-woocommerce')),$s,true);
		self::select('typography_preset',__('Typography','nodevora-customer-rewards-for-woocommerce'),array('default'=>__('Default','nodevora-customer-rewards-for-woocommerce'),'compact'=>__('Compact','nodevora-customer-rewards-for-woocommerce'),'modern'=>__('Modern','nodevora-customer-rewards-for-woocommerce')),$s,true);
		self::select('enable_front_styles',__('Enable Nodevora front styles','nodevora-customer-rewards-for-woocommerce'),array('yes'=>__('Yes','nodevora-customer-rewards-for-woocommerce'),'no'=>__('No','nodevora-customer-rewards-for-woocommerce')),$s,true);
		echo'</div>';
		foreach(self::groups()as$prefix=>$group){echo'<details class="nodevora-advanced" data-preview-group="'.esc_attr($prefix).'"><summary>'.esc_html($group).'</summary><p>'.esc_html__('Leave a color empty to keep the general design. Only explicit overrides replace general values.','nodevora-customer-rewards-for-woocommerce').'</p><div class="nodevora-fields">';foreach(Rewardly_Loyalty_Design::component_variables()as$key=>$unused){if('notice'===$prefix&&'card_background'===$key){continue;}self::field($prefix.'_'.$key,$labels[$key],$s,true);}echo'</div></details>';}
		echo'<p><button type="button" class="button" id="nodevora-design-reset">'.esc_html__('Reset this preset and all design overrides','nodevora-customer-rewards-for-woocommerce').'</button></p>';submit_button();echo'</div><aside class="nodevora-preview"><h3>'.esc_html__('Live preview','nodevora-customer-rewards-for-woocommerce').'</h3><div class="nodevora-preview-tools"><button type="button" class="button" data-preview-width="desktop">'.esc_html__('Desktop','nodevora-customer-rewards-for-woocommerce').'</button><button type="button" class="button" data-preview-width="mobile">'.esc_html__('Mobile','nodevora-customer-rewards-for-woocommerce').'</button><label for="nodevora-preview-component">'.esc_html__('Component','nodevora-customer-rewards-for-woocommerce').'</label><select id="nodevora-preview-component">';foreach(self::groups()as$key=>$label){echo'<option value="'.esc_attr($key).'">'.esc_html($label).'</option>';}echo'</select></div><iframe title="'.esc_attr__('Nodevora design preview','nodevora-customer-rewards-for-woocommerce').'" id="nodevora-preview-frame" sandbox="allow-same-origin"></iframe><p id="nodevora-preview-contrast" role="status"></p></aside></div></form>';
	}
	public static function enqueue() {
		wp_enqueue_style('wp-color-picker');wp_enqueue_script('nodevora-design-admin',REWARDLY_LOYALTY_URL.'assets/js/admin-design.js',array('jquery','wp-color-picker'),filemtime(REWARDLY_LOYALTY_PATH.'assets/js/admin-design.js'),true);
		wp_localize_script('nodevora-design-admin','nodevoraDesign',array('choose'=>__('Choose color','nodevora-customer-rewards-for-woocommerce'),'presets'=>Rewardly_Loyalty_Design::presets(),'variables'=>Rewardly_Loyalty_Design::component_variables(),'selectors'=>Rewardly_Loyalty_Design::component_selectors(),'css'=>REWARDLY_LOYALTY_URL.'assets/css/loyalty.css','invalid'=>__('Enter a valid HEX color, for example #0b1638.','nodevora-customer-rewards-for-woocommerce'),'disabled'=>__('Custom design is disabled. Saved colors are retained.','nodevora-customer-rewards-for-woocommerce'),'contrast'=>__('Check contrast: button text may be difficult to read.','nodevora-customer-rewards-for-woocommerce'),'example'=>__('Example loyalty rewards','nodevora-customer-rewards-for-woocommerce'),'balance'=>__('Example balance: 300 points','nodevora-customer-rewards-for-woocommerce'),'button'=>__('Use my points','nodevora-customer-rewards-for-woocommerce'),'info'=>__('This is a design preview. No points are changed.','nodevora-customer-rewards-for-woocommerce')));
	}
}
